#include <stdint.h>
#include <string.h>
#include NVIM_BASE64_C

// Equivalence proof for tool patch 'load32' (generated by tool_patches.py).
void harness(void) {
  // The statements read only s[src_i .. src_i + 7], so covering every value of
  // those bytes covers every call. No assumptions: buf is fully nondeterministic.
  uint8_t buf[8];
  const size_t src_i = 0;
  const uint8_t *s = buf;
  uint32_t before, after;
  {
    uint32_t bits_h;
    memcpy(&bits_h, &s[src_i], sizeof(uint32_t));
    const uint32_t bits_be = htobe32(bits_h);
    before = bits_be;
  }
  {
    const uint32_t bits_be = ((uint32_t)s[src_i] << 24) | ((uint32_t)s[src_i + 1] << 16)
      | ((uint32_t)s[src_i + 2] << 8) | (uint32_t)s[src_i + 3];
    after = bits_be;
  }
  __CPROVER_assert(before == after, "load32: rewrite equals original");
}
